import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Licensing","description":"","frontmatter":{},"headers":[],"relativePath":"Licensing.md","filePath":"Licensing.md","lastUpdated":1788563284000}'),s={name:"Licensing.md"};function r(o,e,h,l,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h1><h2 id="the-software" tabindex="-1">The software <a class="header-anchor" href="#the-software" aria-label="Permalink to &quot;The software&quot;">​</a></h2><p>AniSphere is released under the <strong><a href="https://www.gnu.org/licenses/gpl-3.0.html" target="_blank" rel="noreferrer">GNU General Public License version 3 or later</a></strong>.</p><p>In practice that means you may use it, study it, change it and share it, and anything you distribute that is built on it has to carry the same freedoms. It also means the software comes with no warranty, which sections 15 and 16 spell out.</p><p>The full text is in <code>LICENSE</code> in the repository.</p><p>There is no per-file licence header. GPLv3 does not require one, and five hundred files of boilerplate is the opposite of readable. The licence is declared once in <code>LICENSE</code>, once in <code>package.json</code>, once in <code>Cargo.toml</code>, and once in the bundle configuration so the installers carry it.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>The Rust and npm trees are overwhelmingly MIT and Apache-2.0, both of which combine with GPLv3 without trouble. Anything under a licence that does not, such as SSPL or a source-available licence, cannot be added.</p><p>Check before adding a dependency:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tree</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><h2 id="bundled-artwork" tabindex="-1">Bundled artwork <a class="header-anchor" href="#bundled-artwork" aria-label="Permalink to &quot;Bundled artwork&quot;">​</a></h2><p>The wallpapers and preset avatars that ship inside the application are credited in <code>ATTRIBUTION.md</code>, with the creator and source for each one where those are known.</p><p>The application icon, logo and interface artwork are original work by the contributors and fall under the project&#39;s GPLv3 licence.</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><p>AniSphere reads from several services, each with its own terms. <code>ATTRIBUTION.md</code> lists them with the endpoint used and a link to the terms.</p><p>One deserves highlighting because it carries an actual obligation rather than a courtesy:</p><p><strong><a href="https://github.com/manami-project/anime-offline-database" target="_blank" rel="noreferrer">manami-project / anime-offline-database</a></strong> is released under the <strong>Open Database License v1.0 plus the Database Contents License v1.0</strong>. ODbL is a copyleft licence for databases and <strong>requires attribution</strong>. That attribution is the entry in <code>ATTRIBUTION.md</code>, and it must stay there.</p><h2 id="anime-itself" tabindex="-1">Anime itself <a class="header-anchor" href="#anime-itself" aria-label="Permalink to &quot;Anime itself&quot;">​</a></h2><p>Nothing about any of the above applies to the anime. Titles, cover art, banners, character images and the media itself belong to the studios and licensors that made them. AniSphere redistributes none of it, and everything it displays is fetched at runtime and cached locally. See <a href="./Legal-Disclaimer">Legal Disclaimer</a>.</p>`,19)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
